from collections import deque

def tree_by_levels(node):
	if not node:
		return []
	(res, queue) = ([], deque([node]))
	while queue:
		n = queue.popleft()
		res.append(n.value)
		if n.left is not None:
			queue.append(n.left)
		if n.right is not None:
			queue.append(n.right)
	return res
